Oh my! Oh my! A checkout component without a test suite! The probability of defects reaching production is approximately 97.6%! Most distressing!

R2, we must document every possible scenario. I am fluent in over six million forms of technical writing, and I shall apply them all to this React Testing Library endeavor!

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange - Mock contexts (oh, the protocols we must observe!)
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Hyperdrive Motivator', price: 99.99 },
  { id: '2', name: 'Protocol Droid Polish', price: 24.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 124.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component - Complete Protocol Documentation', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-3PO-001' });
  });

  describe('Happy Path - The Proper Sequence of Events', () => {
    it('should complete full checkout flow from shipping to confirmation', async () => {
      // Arrange
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Act - Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Tatooine Lane');
      await user.type(screen.getByLabelText(/city/i), 'Mos Eisley');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'C-3PO');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review step
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('ORD-3PO-001');
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-3PO-001');
    });
  });

  describe('Form Validation - Oh dear, invalid input!', () => {
    it('should display shipping validation errors for empty fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('should reject invalid ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip/i), 'WRONG');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Accessibility - Protocol demands proper ARIA!', () => {
    it('should have no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });

  describe('Edge Cases - Most irregular situations!', () => {
    it('should display empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
```

